style.css:
@-moz-document domain("youtube.com") {
/* =========================================================
     1. FONDO PRINCIPAL (Pega aquí el enlace de la imagen)
     ========================================================= */
  ytd-app,
  html,
  body {
    /* Reemplaza URL_DE_LA_IMAGEN por el link directo de Pinterest (.jpg o .png) */
    background-image: linear-gradient(rgba(15, 10, 20, 0.82), rgba(15, 10, 20, 0.88)), 
                      url("https://i.pinimg.com/originals/TU_ENLACE_AQUI.jpg") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* =========================================================
     2. TRANSPARENCIAS Y BARRAS (Estilo Decepticon / Tarn)
     ========================================================= */
  /* Barra superior de búsqueda */
  #masthead-container.ytd-app,
  ytd-masthead {
    background-color: rgba(24, 14, 34, 0.85) !important;
    backdrop-filter: blur(8px) !important;
    border-bottom: 1px solid #8a2be2 !important;
  }

  /* Menú lateral izquierdo */
  #guide-content.ytd-app,
  ytd-mini-guide-renderer {
    background-color: rgba(20, 12, 28, 0.85) !important;
    backdrop-filter: blur(6px) !important;
  }

  /* Hacer transparentes los contenedores principales para que se vea el fondo */
  ytd-browse,
  ytd-watch-flexy,
  #primary,
  #secondary,
  #page-manager.ytd-app,
  ytd-two-column-browse-results-renderer,
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer {
    background: transparent !important;
  }

  /* =========================================================
     3. DETALLES DE COLOR (Acentos Morados y Carmesí)
     ========================================================= */
  /* Barra de progreso del reproductor */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background-color: #9b30ff !important; /* Morado Decepticon */
  }

  /* Barra de búsqueda */
  #search-form #container.ytd-searchbox {
    background-color: rgba(35, 20, 50, 0.9) !important;
    border: 1px solid #6a1b9a !important;
  }

  /* Títulos y textos principales */
  #video-title.ytd-rich-grid-media,
  ytd-watch-metadata #title h1 {
    color: #f3e5f5 !important;
    text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.9);
  }

  /* Tarjetas de video con ligero fondo oscuro para legibilidad */
  ytd-rich-item-renderer {
    background-color: rgba(25, 15, 35, 0.55) !important;
    border-radius: 12px !important;
    padding: 6px !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;
  }

  ytd-rich-item-renderer:hover {
    transform: translateY(-3px) !important;
    box-shadow: 0 4px 15px rgba(155, 48, 255, 0.4) !important;
  }
}
